def standard():
    b = Symbol('b')
    ps = [Rational(1, 10), b, Rational(1, 5), b, Rational(1, 10)]
    bv = solve(Eq(sum(ps), 1), b)[0]
    ps = [p.subs(b, bv) for p in ps]
    return 5*sum(p*x**2 for p, x in zip(ps, range(1, 6)))

def unique():
    return [standard()]
